/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState } from 'react'
import { Button, Table, Alert, Spin, Empty, Input, Col } from 'antd'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { RowWithMargin } from '../../../../EmployeeBenefits/CommonComponents'
import { ColTextAlignRight } from '../../../../EmployeeBenefits/CommonComponents/index.style'
import { permissionColumns } from './constants'
import { useRoles } from '../../../state/hooks/useTeamContext'
import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import AddPermissionModal from './addPermission'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'

const { Search } = Input

const UserPermissions = ({ history, ...props }) => {
  const { getPermissionList, permissionListData } = useRoles()
  const [{ PERMISSION_LIST_ERROR, permissionListStatus }] = useErrorContextValue()
  const [{ PERMISSION_LIST_LOADER }] = useLoaderContextValue()
  const [searchText, setSearchText] = useState(null)
  const [addModalVisible, toggleAddModal] = useState(false)

  const getFilteredData = () => {
    if (searchText) {
      return permissionListData.filter(permission => new RegExp(searchText, 'i').test(permission.name) || new RegExp(searchText, 'i').test(permission.codename))
    }
    return permissionListData
  }

  useEffect(() => {
    getPermissionList()
  }, [])

  return (
    <EbEmptyPage
      history={history}
    >
      <Spin spinning={!!PERMISSION_LIST_LOADER}>
        {(PERMISSION_LIST_ERROR) && <Alert type='error' message={permissionListStatus} banner />}
        <RowWithMargin type='flex' justify='space-between'>
          <Col span={14}>
            <h2>Permission List</h2>
          </Col>
          <Col span={6}>
            <Search
              placeholder='Search..'
              // onSearch={handleSearch}
              onChange={(e) => setSearchText(e.target.value)}
              disabled={PERMISSION_LIST_ERROR || !Array.isArray(permissionListData)}
              // allowClear
            />
          </Col>
          <PermissionCheckerV2 requiredPermission='ops.can_perform_team_actions'>
            <ColTextAlignRight span={4}>
              <Button
                type='primary'
                onClick={() => toggleAddModal(true)}
              >
                Add New Permission
              </Button>
            </ColTextAlignRight>
          </PermissionCheckerV2>
        </RowWithMargin>
        {
          !PERMISSION_LIST_ERROR && Array.isArray(permissionListData)
            ? (
              <Table
                columns={permissionColumns}
                dataSource={getFilteredData()}
              />
              )
            : <Empty />
        }
      </Spin>
      <AddPermissionModal
        visible={addModalVisible}
        toggleAddModal={toggleAddModal}
      />
    </EbEmptyPage>
  )
}
export default UserPermissions
