/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect } from 'react'
import { Modal, Form, Alert, message, Spin, Input } from 'antd'
import { usePermissionsContext, useRoles } from '../../../state/hooks/useTeamContext'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { addPermissionFormItemConfigs } from './constants'

const AddPermissionModal = ({ visible, form, toggleAddModal }) => {
  const { getFieldDecorator } = form
  const { addPermissionRequest, resetState } = usePermissionsContext()
  const { getPermissionList } = useRoles()
  const [{ ADD_PERMISSION_ERROR, addPermissionStatus, addPermissionErrorData }] = useErrorContextValue()
  const [{ ADD_PERMISSION_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()

  const handleOk = () => {
    form.validateFields((err, values) => {
      if (!err) {
        addPermissionRequest({
          ...values
        })
      }
    })
  }

  useEffect(() => {
    if (addPermissionErrorData && addPermissionErrorData.error) {
      const error = addPermissionErrorData.error
      for (const key in error) {
        const values = form.getFieldsValue()
        form.setFields({
          [key]: {
            value: values[key],
            errors: Array.isArray(error[key]) && error[key].map(err => new Error(err))
          }
        })
      }
    }
  }, [addPermissionErrorData])

  useEffect(() => {
    if (addPermissionStatus === 'success') {
      message.success('Permission added successfully.')
      form.resetFields()
      toggleAddModal(false)
      getPermissionList()
      resetState(['addPermissionData'])
      resetError(['addPermissionStatus'])
    }
  }, [addPermissionStatus])

  return (
    <Modal
      visible={visible}
      title='New Permissions'
      okText='Create'
      onCancel={() => toggleAddModal(false)}
      onOk={handleOk}
    >

      {(ADD_PERMISSION_ERROR && !addPermissionErrorData) && <Alert type='error' message={addPermissionStatus} banner />}
      <Spin spinning={!!ADD_PERMISSION_LOADER}>
        <Form>
          <Form.Item
            label='Codename'
          >
            {
              getFieldDecorator(
                'codename',
                addPermissionFormItemConfigs.codename
              )(
                <Input />
              )
            }
          </Form.Item>
          <Form.Item
            label='Description'
          >
            {
              getFieldDecorator(
                'name',
                addPermissionFormItemConfigs.name
              )(
                <Input />
              )
            }
          </Form.Item>
        </Form>

      </Spin>
    </Modal>
  )
}
export default Form.create({ name: 'new-permission' })(AddPermissionModal)
